// Build notification_context_json and detect client action items
const data = $input.first().json.body || $input.first().json;
const openItems = data.open_items || [];

const clientKeywords = ['client', 'owner', 'select', 'confirm', 'approve', 'decide', 'choose'];
const hasClientItems = openItems.some(item =>
  clientKeywords.some(kw => item.toLowerCase().includes(kw))
);

return {
  project_json: JSON.stringify(data),
  notification_context_json: JSON.stringify({
    project_name: data.project_name,
    client_name: data.client_name,
    phase: data.phase,
    next_site_visit: data.next_site_visit,
    has_client_action_items: hasClientItems
  })
};

